#!/usr/bin/env bash
# PreToolUse hook（Agent）：派发那一刻查派发提示齐不齐、写得对不对，缺一样当场拒（退出 2，stderr 写原因与出路）。
# hook-events: PreToolUse:Agent PreToolUse:Task
# admission: always Claude Code 在主 agent 每次派发之前调它，判的是这一次的派发提示与此刻会话里在跑的子 agent
# run-condition: command python3
#
# 判法（judge_dispatch）：各条都判完，不成立的按下面的次序一次列全、每条带自己的出路，有一条不成立就拒；哪些情形拒、哪些放照各条写的：
#   ① 重型测试一行：派任何类型，提示里要有一行「重型测试：不跑」（重型测试只由主 agent 跑）（行首可带 - * > 与粗体）。
#      有那一行也照判提示正文里许可子 agent 跑 checker 档 / 重型测试的句子（heavy_permission_sentences），有一句就拒、引出那几句：
#      许可词（可以、允许、准许、能、可……）后面八个字以内接跑 / 执行，同一句里又有 checker 档、--include-ignored（前面最近点名的包是别的包的不算）、重型测试
#      或起测试而点名 checker 档包的 cargo（`cargo test -p singlefs-checker-tier …`，带 --no-run 的不算）、或两档里有轻型的那三条的重型写法
#      （crash-point-replay.sh、checker-tier-formal-verification.sh、checker-tier-crates-mutation-replay.sh 后面同一段命令里——反引号里的到反引号为止、不在反引号里的到子句末——
#      没有 --quick、--list、--list-items、--selftest、--tool-versions、--write 的；heavy_permission_light_capable_runs）；「只跑」与 checker 档同一个子句；
#      「跑 harness 档或 … checker 档」；跑 / 执行之后同一子句里有起测试而点名 checker 档包的 cargo 或那三条的重型写法。前面紧挨否定的（不跑、不带、非、拦……）、
#      轻型那三条带 --quick（可再带 --item）的写法许可子 agent 跑照放（.claude/rules/verification.md「两档：轻型与重型」）；
#      同一子句后面写了不跑 / 归提交 / 重型的、后面接 clippy / build / 编译的不算；「」『』“”里的转述、「重型测试：不跑」那一截、提到主 agent 的子句不判。
#      判的只是这几种字面形，别的说法（「checker 档的用例你自己验一下」）认不出；执行时 heavy-test-guard.sh 与看门狗的进程一层照旧兜底。
#   ⑫ 内置通用类型（general-purpose、claude，或不给 subagent_type）一律拒：一次性的活派项目定义 clerk（起步不带 CLAUDE.md 与规则），只读搜索派 Explore；
#      确要派内置类型，提示里写一行「通用已判：<为什么 clerk 做不了>」放行。
#   ⑬ 骨架的占位没填完：提示里还有 `<填 …>`（scripts/agents/dispatch-prompt.py 打出来的占位）就拒，逐个列出那几行。
#   ② 不读共用约束的类型（Explore、写了放行行的通用类型，或没有定义文件的类型）：提示里要有「开工先读」与 `.claude/agent-common.md`。
#   ③ 输入齐不齐：`.claude/agents/<类型>.md` 的 frontmatter 有 `required-inputs:` 的，逐组查——组之间逗号分隔，组内 `|` 分隔的同义词在提示里出现一个就算；
#      定义不在、没写这一行的不查。
#   ④ 写范围：类型在 `.claude/hooks/agent-write-scope.tsv` 里的，提示里报告行（行首或句首的报告标签，⑰ 的「在哪都认」不用在这里）点名的路径（报告行的解析与 ⑰ 共用一份，report_line_mentions，写法在 ⑰ 条下）
#      与「写进 / 写到 / 更新」后面紧跟的路径（工作根与过渡期旧根下的、research/、.claude/、crates/、litmus/、records/ 起头）逐个按它那几行模式判，不在里面就拒；
#      前面六个字以内有否定词的不判；报告行里还有 <填 …> 占位的交 ⑬，这里不判。
#      工作根（默认 ~/.local/share/singlefs/work/）认展开的绝对路径与 ~/…、$HOME/…、$SINGLEFS_WORK_ROOT/… 几种写法，过渡期旧根认 /tmp/claude-<uid>/，
#      读表、模式转正则与表里 $SINGLEFS_WORK_ROOT/ 起头的模式怎么展开在同目录的 lib_write_scope.py（write-guard.sh、bash-command-detector.sh 调的是同一份，读不到它时 ④ 不判，stderr 写一句），
#      工作根怎么认只在同目录的 lib_work_root.py；旧根在跑的子 agent 与别的会话的子 agent 都交回之后由主 agent 撤（撤法在那份库的文件头）。
#   ⑤ 实现员与工具员撞文件（writer_collision_verdict）：实现员要有一行「要动的 crates 文件：…」（份数不设上限，用户 2026-09-27 定；`crates/mutations.tsv` 只追加、不算撞）；
#      工具员的文件取「要改的文件」（tooling_writer_files：行首「要改的文件：」一行里的路径，值空着的接下面连着的列表项；标题是「要改的文件」那一节到下一个标题；
#      闭合围栏块里的不算；从仓根起、带 / 的词，以 / 收尾的是目录、罩住底下的文件；认不出路径的不拒、登记一份空的；拆分提案第十九节 ②）。
#      与本会话还在跑的实现员、工具员登记的文件有交集就拒（实现员对实现员、工具员对工具员、实现员对工具员都算）。登记在 <DISPATCH_GUARD_STATE_ROOT>/<会话 id>/implementation-writers.tsv，一行一次派发
#      （时刻、提示的 sha256、文件、类型；改前只登记实现员、一行三列，读到三列的当实现员）；每次判之前先删掉已结束的：主会话记录里那次派发（toolUseResult 的 prompt 同 sha256）的 agent
#      交回了（`<agent-message from="<id>">` 后跟 `[Subagent hand-back]`）、任务通知是 failed / killed / stopped、或被 TaskStop 停了、或 TaskStop 报找不到它
#      （结果是「No task found with ID: <id>. Running background agents: …」而同一句的在跑名单里没有它：中断之后没起来的那件）；
#      派发之后 10 分钟主会话记录里还没有它的，按没派出去删。
#   ⑥ 快照冲突：派 kb-scribe、implementation-writer 时要改的文件在还没判完的三方轮开工快照里，拒（哪几轮开着、快照清单怎么读、放行行与拒绝说明在同目录的
#      lib_snapshot_conflicts.py，与 scripts/gate/apply-writer-patch.py 打补丁之前那一查共用；要改的文件怎么从提示里找见 snapshot_conflict_verdict）。
#      快照清单读不了（是目录、没有读权限、悬空的链接）的那一份不判，照「放行但必记检出」放行：stderr 点名那一轮与那份清单、写出路，放行时往检出记录
#      （AGENT_HOOK_DETECTIONS，没设取 lib_work_root.py 的 default_detections_path）追加一行、结局只记，看门狗据此报给主 agent（lib_snapshot_conflicts.py 的 unreadable_lines、record_unreadable）。
#      ⑥ 自己出错（判法抛异常、读不到 lib_snapshot_conflicts.py）照常放行时同样照「放行但必记检出」：stderr 照旧写那一句，放行时往同一份检出记录追加一行、结局只记
#      （findings 以「派发闸没判全、照常放行」起头，record_unjudged）。
#      用户叫停、不写判决的轮，在 research/prompts/abandoned-rounds.tsv 登记一行收掉（门禁 doc-process-records 的 abandoned-rounds 格读的是同一张表，只有这一处登记；
#      <轮>-halted.md 这一支已撤，写了也不认）。一行收不收的判法只在同目录的 lib_abandoned_rounds.py 一份，门禁那一格调同一份（不收就是红）：
#      第一列是轮名，四列不空，第二列日期是 YYYY-MM-DD，同一轮只一行；整行里要有出处「records/<文件>.md 第 N 行〔<原话>〕」（或 records/<文件>.md:N〔<原话>〕），
#      〔〕里照抄出处那一行里的一段原话（原话所在的那一行含这一轮的名字）；文件是 records/ 下现存的 .md（路径里没有 ..，解到真路径后仍在 records/ 之内），
#      拿原话在那份文件里找：恰好命中一次的取命中的那一行（行号只当提示，对不上而原话找得到照收）；命中几处而行号提示正落在其中一处的取提示那一行；
#      原话找不到而行号提示那一行还有这一轮的名字、〔〕与那一行去掉 .claude/kb/term-renames.md 登记的新旧名与日期（再去掉空白与逗号）之后〔〕逐字落在那一行里的
#      （只经过术语改名、删日期）取提示那一行；没带原话、找不到而提示那一行没有这一轮的名字、找不到而提示那一行去掉新旧名与日期之后对不上（〔〕写的是转述、
#      改了别的字）、命中几处而提示不在其中都不收。
#      取到的那一行里有这一轮的名字（前后不连着轮名字符）、
#      除这一轮外没有别的轮名（别的轮名 = 仓里认得的轮名全集 ∪ 形如 <名>-r<数字> 的写法：全集是 research/prompts/ 下 _<轮>-body.md、<轮>-snapshot/、<轮>-main-verification.md 的轮名
#      加登记表第一列，-r 形不看仓里有没有它的材料；同一行里别的轮的叫停原话不收）、并有一句「」括起来的用户原话（去掉空白后至少 6 个字）。
#      不要求出处的只有库里写死的旧行名单（LEGACY_SOURCELESS_ROUNDS：c196-r1、d16-item1-r2、c364-r3、smalldata-ttime-r1，只缩不涨，不按日期判），门禁那一格用同一张名单，名单外的行一律要出处。
#      指到这一轮自己的材料（research/prompts/<轮>*、_<轮>*）、规则与定义文件、仓外路径、别的轮的叫停原话、日期写坏、同一轮两行、
#      原话找不到（行号提示那一行没有这一轮的名字，或去掉新旧名与日期之后对不上）或命中不止一次（行号提示不在其中）的都不收，那一轮照旧算开着，拒绝说明里写没收的原因。
#      钩子认不出那句话是不是用户为这一轮说的（〔〕逐字照抄了同一轮另一句带名字与「」原话的话时也照收），那一半靠主 agent 核。
#      读不到 lib_abandoned_rounds.py 时 ⑥ 不收任何叫停的轮（登记表当没有），stderr 写一句。
#   ⑦ 并发与模型：本会话还在跑的子 agent（不分模型；主会话记录里派出去、没结束、会话记录 3 小时内动过或 3 小时内派的）
#      已有 SUBAGENT_CONCURRENCY_LIMIT 个（5，用户 2026-10-02 定）就拒，没有放行行。同一条消息里并行派的几个，后几个判的时候前几个可能还没写进主会话记录，数不到。另外，主会话记录里 8 天内有 failed 任务通知写着「resets <时刻> (<时区缩写>)」、它的
#      「model sent to the API」与新派的同一族（opus / sonnet / haiku），而现在还没到那个时刻，拒；那次失败之后同一族又派出去、没再撞限额的
#      算窗口已解开（换了账号或提前恢复），不拒；放行行「限额窗口已判：<理由>」。
#   ⑧ 书记员：提示里点名的工作根或过渡期旧根下的规格文件逐份交给 scripts/kb/kb-spec-check.py，红了拒；一份认得出的规格都没有也拒
#      （规格写在提示正文里的，把提示正文当规格判）；放行行「规格检查已判：<理由>」。
#   ⑨ 设计员写重跑登记（提示里有 research/prompts/e<号>-r<n>-prereg.md）：`scripts/gate/admission.py experiment <根> E<号>` 退 77
#      （这一实验的单元键与上次产物头记的相同）就拒；没登记的实验（退 2）放行；放行行「准入已判：<理由>」。
#   ⑩ 变异分诊员：提示里要有 `scripts/mutation/tables/…tsv` 或 `crates/mutations.tsv`——不接没有表的广谱活动。
#   ⑪ 执行员：提示里写着「只修锚点」或「只补落产物」的放行这一条；否则要有「这一段回答的岔路：<非空>」；提示里第一处点名的登记（registration_has_segment，拆分提案第二十四节 ①）
#      已经有过一段的算续做：原登记 research/prompts/e<号>-preregistration.md 看实验页在不在，第 n 次重跑的登记 e<号>-r<n>-prereg.md 看实验页（中文那一份）有没有一行标题
#      （两到六个井号）写着「第 n 次重跑」（阿拉伯数字或中文数字，「未跑 / 没跑」紧跟着的不算）——新的 r<n> 第一段不算续做，只要「这一段回答的岔路」；
#      续做还要有「上一段岔路表里还差：<非空>」，写「无 / 没有」的拒（一行都不差就该交岔路表，不续派），再要有一行行首「承接：<上一段执行员的报告路径>」
#      （「上一段报告：」「上一份报告：」也认；值里的路径至少一份在，~、$HOME、$SINGLEFS_WORK_ROOT 照展开，相对路径从仓根起；常设要求 B8，拆分提案第一百二十二节 ⑨），
#      没有或点到的都不在的拒；占位的交 ⑬。
#   ⑭ 任务带长活的类型（LONG_RUN_AGENTS：experiment-designer，加 ⑮ 那张类型表）的预计挂钟与长活声明（判法在同目录 lib_long_run.py，判据
#      .claude/rules/test-script-discipline.md「用上现有的硬件加速」「判定可复用：按输入存，按前缀剪」）：
#      要有一行「预计挂钟：2 小时内」或「预计挂钟：超过 2 小时」（后面可接逗号与推的依据），没有或认不出就拒；
#      超过的，同一份提示里要有「分片：」「续跑：」「多机：」三行：多机一行只认骨架那一句规范写法（lib_long_run.py 的 CANONICAL_HOSTS_SENTENCE，逐字：台数从 crash-point-replay-shard-configuration-check.sh --emit-hosts 读，
#      每台线程取 .claude/heavy-thread-default 的登记值，不现算、不写常量），这一行逐字等于它（可带句末句号），后面不许接任何说明（「；……」「，……」都拒），说明另起一行照普通正文写，
#      别的写法一律拒（不再用现算词表去拦）、不许写死台数线程内存；
#      缺的由一行「分不了：」点名（至少 8 个字），不齐就拒。在 ⑦ 之后、⑧ 之前判；lib_long_run.py 读不到时不判，stderr 写一句，照「放行但必记检出」往检出记录追加一行（见 ⑥ 的写法，拆分提案第九十四节 ①）。
#      「分片：」「续跑：」「多机：」每个标签只写一行：同一个标签出现第二行就拒（只读第一行，第二行写什么都没人判；lib_long_run.py 的 duplicate_prompt_problems），拒绝说明写「只写一行」，
#      要补充的另起一行写成不以那个标签起头的普通正文。
#      放行行「多机已判：<理由>」：用户给了逐台不同的台数或线程时写，逐台参数另起一行照普通正文写；有这一行时子 agent 照提示里逐台写的参数跑，没有就只照「多机：」那一句规范句。
#      这一行理由不能空、不能是占位，只写一行，写坏了拒（hosts_valve_problems）；它不放宽别的：「多机：」一行照旧只认规范句、同一标签写两行照拒。与 ⑮ 一样不判代码块（照 CommonMark，闭合了的围栏块）里的行：预计挂钟、分片、续跑、多机的示例行放进代码块不被当成声明那一行，也不算重复；认代码块与 ⑮ 同一个函数、同一种认法（⑮ 条下写全）。
#      脚本文件头的 # long-run-hosts: 与派发提示同一种登记值读法（judge 的 hosts_reading="registered"，detached-run.sh 与 host-dispatch.py 经 judge_script_header 判）；
#      只有 .claude/long-run-live-hosts-exempt 登记、登记的 sha256 又对得上这份脚本现在文件的脚本文件头按现算读（sha256 对不上判红）。文件头写的读法与脚本真做的事是否一致，钩子看不到，由写的人保证。
#      超过 2 小时的另判两样（long_run_line_value_problems；records/2026-09-16-subagent拆分提案.md 第九十节 ⑤，常设要求 B6、B2b）：
#      要有一行「复用：<判定按什么入库、键相同的怎么沿用>」，这一件不产出判定的写「复用：无判定：<为什么>」；这一行不是占位、不短于 8 个字，「分不了：」顶不了它；
#      「分片：」「续跑：」写了的不短于 8 个字（拦「好」这类空话；分片真能分、续跑真能续，钩子看不到）。「复用：」与另三个标签同一套：同一标签写第二行拒、闭合了的围栏代码块里的行不判、
#      标签行两种围栏认法遮不遮不一致的拒。
#   ⑮ 线程上限：提示里行首「线程上限：」后面只认一个十进制整数，整数后面什么都不接，括注也不行（任何括注都拒，不看里面写了什么）；要说明的另起一行照普通正文写，那一行不以「线程上限：」起头就不判；
#      代码块（照 CommonMark，闭合了的围栏块）里的行不判（示例行、喂法样本放进去不被当成这一行，里面的「线程上限已判」也不当放行行）；没闭合的围栏块里的行照判；
#      ⑭ 与这一条经同一个函数（without_code_blocks）认代码块，认法交 CommonMark 参照实现（markdown-it-py 的 commonmark 预设，本机 python3-markdown-it 3.0.0）：
#      反引号与波浪线围栏、列表项与引用块里的围栏都认；只遮闭合了的围栏块（块的最后一行去掉引用块的 > 与缩进之后，是同一种围栏字符、不短于开头那一行），
#      到文末没闭合的、在列表项或引用块结束处结束的照判；缩进代码块与 HTML 块（含 <!-- … --> 注释）不遮，里面露出的三个反引号也不开块；
#      行首写在一行里的 ```…``` 是行内代码，不开块。标签行（这一条的「线程上限：」「线程上限已判：」，⑭ 的「预计挂钟：」「分片：」「续跑：」「多机：」「多机已判：」「分不了：」）
#      在这一认法与宽的逐行认法（hidden_lines_by_wide_line_rule：反引号、波浪线都认，每一行先去掉行首的 > 与任意缩进，开块那一行往后第一行同一种字符三个以上、后面只有空白的当关块，
#      反引号开块那一行后面不许再有反引号）下遮不遮不一致就拒（code_block_ambiguous_label_lines），拒绝说明逐行写两种认法各怎么认、叫把围栏写规整；
#      代价：四个反引号套三个反引号的示范（外层四个、里面三个）也拒，示范围栏的外层用 ~~~。载不进 markdown-it-py 时不比两种认法，退回宽的逐行认法遮，stderr 写一句；
#      整数要等于登记的每台默认重活线程数
#      （.claude/heavy-thread-default，经 scripts/hosts/heavy_threads.py 的 default_heavy_threads 取，不看 SINGLEFS_THREAD_CAP 这类临时覆盖；
#      用户 2026-10-12 定：没给参数每台默认登记值，双机两台各一份）。出现 ÷、/、「一半」、两个及以上数字、整数后面接括注或别的话（「31 的一半，即 15」「31（本机）」「31（机器忙时按负载降）」）、
#      不等于登记值、认不出数的都拒。派 THREAD_LIMIT_REQUIRED_AGENTS（implementation-writer、investigator、tooling-writer、experiment-runner、mutation-triage、
#      three-way-attack、clerk、three-way-forward、three-way-defense）而提示里没有这一行也拒；别的类型没写这一行不判。后三种里 clerk 的定义许编译、跑编译出来的代码，
#      three-way-forward、three-way-defense 的定义只跑模型目录里的 tools/rerun.sh、不编译；三种多数派发并不带重活，不带重活的用放行行顶缺行。
#      放行行「线程上限已判：<理由>」（用户给了参数、内存装不下、这件活不起重活这类）两种拒（缺行与写的不对）都放；拒绝说明的出路分两种写：
#      要别的数的写「线程上限：N」再加已判行，单独的已判行只给确实不起重活的活（子 agent 拿到只有已判行的提示不起重活，要起就停下交回）。
#      N 是 <填 …> 占位（SKELETON_PLACEHOLDER，⑬ 认的那一种）的交 ⑬；别的尖括号写法（<登记值>、<按机器忙闲定>）按认不出数拒，不当占位；读不到登记时放行、stderr 写一句。
#   ⑯ 草稿目录写者锁（判法与锁的格式在同目录 lib_writer_lock.py，认锁的一半在 write-guard.sh 第九道）：提示里行首「草稿目录：<工作根或过渡期旧根下的目录>」（工作根本身不算）点名的目录
#      （那一行怎么认只在同目录 lib_prompt_scratch_line.py，与 ⑰、完工清理闸、交回闸 ⑥ 共用；列表、引用记号与粗体起头的不认），
#      那一行（单看这一行 scratch_line_values 认得出路径的）在那份库的围栏认法（fenced_line_numbers：照 CommonMark，没收尾的遮到文末）与宽的逐行认法
#      （hidden_lines_by_wide_line_rule，⑮ 条下写全：找不到关块的那一行不开块）下遮不遮不一致的拒（scratch_line_fence_ambiguity）：③ 按字面子串找得到「草稿目录」
#      照样放行，⑯ 却取不到这个目录、不建锁；拒绝说明逐行写两种认法各怎么认、叫把围栏写规整（补上收尾行，或把那一行挪到围栏之前）；--check-prompt 同样拒；
#      派发放行时在里面排他建 .writer-lock（派发它的会话号、派发时刻、提示的 sha256、记录路径、随机串）；目录里已有锁、持锁的子 agent 还在跑就拒
#      （持锁的是认领文件里的那个 agent，没认领的按提示 sha256 与派发时刻在会话记录里找，还没落进记录的 10 分钟内算在跑，在跑的判法同 ⑦；
#      还没落进记录、而这一次的提示与锁里登记的是同一份的，当上一次派发失败后的重试，直接接手）；
#      持锁的已交回 / 失效 / 从没起来，或提示里写了「写者锁已判：<理由>」，新锁接手，旧写者之后写这个目录被 write-guard.sh 第九道拒。
#      锁文件在而判不了（读不了、不是普通文件、不是 JSON 对象、缺 nonce / dispatched_at / prompt_sha256，lib_writer_lock.py 的 lock_state）的，与写闸第九道同一口径
#      按「锁在而判不了」拒：点名那把锁与判不了的原因，出路是主 agent 核过这个目录归谁之后删掉那把锁再派（派发闸重建）；「写者锁已判」行不接手判不了的锁。
#      认领文件坏了（不是 JSON、缺 agent_id）不算判不了：持锁者照提示 sha256 与派发时刻在会话记录里找，接手时那份坏认领跟旧认领一起删。
#      --check-prompt 不建锁、写成「派的那一刻另判」；只有钩子入口（stdin）真读锁、真建锁，自检里直接调 decide 不碰锁文件。
#      读不到 lib_writer_lock.py 时这一条不判、不建锁，stderr 写一句，照「放行但必记检出」往检出记录追加一行（点名那几个草稿目录；拆分提案第九十四节 ①）。
#   ⑰ 报告行：④ 与这一条共用一份报告行解析（report_line_mentions）：标签认「报告」「报告路径」「报告写进」「报告写到」四种。
#      ④ 只在行首或句首认：行首可带 - * > _、粗体与「1.」「2)」这类编号，句首是。！？；之后；句中的（「，报告 <路径>」）不认。
#      ⑰ 的文件名与三方腿形态两判在哪都认，前面连着字的（「交回报告：」「把报告写进」）不认；两边都不认「」『』“”、反引号里引着的
#      （攻方 landing-audit-r2 K2-3：正文里引着的「报告：」被当成报告行、误拦两份合法派发）。引号怎么配（quoted_spans）：「」『』“”照整份提示配对，
#      一句引文折到下一行、后半截照样算引号里的（拆分提案第九十节 ㉟），可以套，没配上的开头不算；反引号按行配对。
#      ⑰ 两判只看报告行里落在本提示草稿目录下的路径与不带目录的裸文件名（「<草稿目录>/…」写法也算在草稿目录下），别的目录下的当转述别的子 agent 的报告，不判
#      （攻方 landing-audit-r3 K2-1、K2-2：行首、句首两种锚法在真提示上各有误拦误放，按位置分不出自己的报告行与转述；用户 2026-10-23 定按草稿目录判）。
#      本提示的草稿目录：行首「草稿目录：」一行点名的、工作根或过渡期旧根底下的目录（report_scratch_directories；认法只在同目录 lib_prompt_scratch_line.py，与 ⑯ 共用，
#      取骨架 scripts/agents/dispatch-prompt.py 打的那一行：句中「，草稿目录 <别处>」、列表「- 草稿目录 <别处>」这类转述不认，「草稿目录在 <路径>」也不认，判决 landing-audit-r4 K2-4、K3-2）；
#      提示里没有这一行的（没写，或写了而那一行点名的不在工作根与过渡期旧根底下）：文件名一判只判不带目录的裸文件名与「<草稿目录>/…」写法，
#      带目录的路径一律当转述、不判（拆分提案第九十节 ㉗：2026-10-14 以前不照骨架写的提示多半没有这一行，那批只罩裸文件名）；三方腿那一判不看草稿目录，
#      本腿的报告路径照下面三方腿那几条判（报告行点名的文件不是三方腿形态时，有这一行才分得出落没落在草稿目录下，没有这一行的只有裸文件名算本提示自己的、拒）；
#      「报告」要接冒号，或接空白再接路径（~、/、$、research/、.claude/、crates/、litmus/、records/ 起头），另三种冒号可有可无；
#      标签之后到行尾是这一行的正文，正文里第一个像路径的词（带 / 或带扩展名）是这一行点名的路径（交 ④ 判写范围、交三方腿判形态），
#      正文里的每个词交文件名判，紧跟在否定词（不、别、勿、禁止，中间隔不到五个字、没有标点）后面的不判（「（不要叫 report.md）」，辩方 landing-audit-r2 K2-4）。
#      闭合了的围栏代码块（照 CommonMark，without_code_blocks）里的行不认。
#      文件名：报告行正文里的文件，名字（路径最后一段，要带扩展名）里带 report（不分大小写）的拒，以 SUMMARY、FINDINGS、ANALYSIS 开头（不分大小写）的 .md 也拒
#      （拆分提案第九十节 ㉑，实测 research/prompts/subagent-landing-audit-2026-10-22/b9-prefix-probe.md：这三个词在名字中间或末尾的、不是 .md 的写得进去，不拦；扩展名照工具层也不分大小写，.MD 照拒、.markdown 放，
#      实测 research/prompts/subagent-landing-audit-2026-10-22/b12-scratch-lib.md「6.1 工具层真调」），出路是改成草稿目录下的 result.md。
#      Claude Code 自带的拦截不让子 agent 用 Write 建名字为 report.md 的文件（工具结果原文「Subagents should return findings as text, not write report files. Include this content in your final response instead.」，
#      不在仓里任何钩子里；2026-10-14 起子 agent 写 report.md 209 次全被拒，名字里带 report 的别的文件 16 次里拒 6 次，progress.md、result.md 写得进去），骨架（scripts/agents/dispatch-prompt.py）默认填 <草稿目录>/result.md。
#      四种标签都判（攻方 landing-audit-r1 K2-4：原来 ④ 只认后三种、⑰ 只认「报告：」，两边各漏一半）；目录名带 report、文件名不带的放行。
#      没有放行行：这一条拦的是工具层必拒的名字，没有「确要写 report.md」的情形。
#      三方腿（类型表只登记在定义 frontmatter 的 leg: three-way 一行，派发那一刻按提示的仓根经同目录 lib_three_way_legs.py 读，three_way_report_types；
#      交回闸、骨架与账表读同一处，拆分提案第九十节 ⑯）另判形态（three_way_report_verdict、leg_report_reading）：要有一处本腿的报告路径 research/prompts/<名>-output.md
#      （形态只在 lib_three_way_legs.py 认，报告行那一支 leg_report_written_tree、整份提示那一支 leg_report_mentions、交回闸 ② 的 leg_report_mentions_in_trees
#      都经那份库的 leg_report_mentions_in_trees 一个函数，三处判得一样：没填的 <轮> 占位、子目录下的、仓外副本里同名的都不认，仓根、./、本仓工作树的绝对路径、
#      ~ 与 $HOME 起头的、../<仓根目录名>/ 这类都认，判决 landing-audit-r4 K2-5、landing-audit-r5「交回闸 ② 仓外报告」，拆分提案第九十节 ㉗；
#      $SINGLEFS_WORK_ROOT/、${SINGLEFS_WORK_ROOT}/ 起头的先照同目录 lib_work_root.py 展开成工作根再交那份库认，与交回闸 ② 同一种解法，work_root_tokens_expanded）。本腿的报告只认两处：
#      报告行点名的（带扩展名的那个词整个是这一形态；它不合形态、又不在本提示草稿目录下也不是裸文件名的，这一行正文里后面合形态的那个词也算：
#      「报告路径（形态 `research/prompts/<轮>-sonnet-output.md`）：research/prompts/x-r1-sonnet-output.md」这种写法），或报告行里一处都没有时，整份提示里不在「」『』“”与反引号里、名字以本腿轮名加「-」起头的
#      （攻方 landing-audit-r3 K2-3：「交付：报告 …-output.md」写法；拆分提案第九十节 ㉗：只认本腿轮名下的，别的轮的判决、腿报告是背景材料，不当本腿的）。
#      本腿轮名（leg_round_names）：行首「背景材料：」一行里的 _<轮>-background.md 或 _<轮>-body.md（三种腿的定义都要这一样输入），与前面不连着字、
#      不在引号里的「轮名」标签后面那个名字（冒号可有可无，可带粗体与一个反引号）；一个都认不出时整份提示那一支一处都不认，只剩报告行。
#      禁读清单那几段（forbidden_list_spans：行首「禁读清单」或「禁读」接冒号的一行到行尾，冒号后面是空的再连着往下的列表项；标题里有「禁读」的一节到下一行标题）
#      里的 -output.md 是别的腿的，不当本腿的报告，报告标签落在里面的也不算报告行；禁读清单里点到本腿自己的报告（与 own 里的 research/prompts/<名>-output.md 一样，
#      引号、反引号里的也算）拒（拆分提案第九十节 ㉙，landing-audit-r4 攻方提示头一版就是这样写的、当时放行）。
#      报告行点名的文件落在本提示草稿目录下或是裸文件名、又不是这一形态的（例如草稿目录下的 result.md）拒，别的目录下的当转述不判；一处本腿的报告都没有也拒，
#      拒绝说明列出认到的本腿轮名、只在禁读清单里的、不在本腿轮名下的与当成转述的报告行。本腿的报告路径另交文件名那一判：名字里带 report 的、以 SUMMARY、FINDINGS、
#      ANALYSIS 开头的拒（拆分提案第九十节 ㉗：它不在草稿目录下，原来不判；共用约束「报告」一节：报告文件名里不带 report）。
#      交回闸 .claude/hooks/handback-guard.sh 只认这种形态（三方腿的报告就是它，.claude/rules/three-way-inference.md「云端腿的报告要分段落盘」），
#      派发时放过草稿目录下的 result.md，腿照做必在交回时被拒（攻方 landing-audit-r1 K3-1）。报告行里还有 <填 …> 占位的交 ⑬，这一判不看那一行。
#      三方腿另要一行行首「报告：」（leg_report_line_verdict；LINE_START 起头，闭合了的围栏代码块里的不算）：没有就拒，句中写的「报告写进 …」「。报告：…」不顶这一行，
#      出路是照骨架写「报告：research/prompts/<轮>-<模型>-output.md」（research/prompts/subagent-landing-audit-2026-10-22/b12-dispatch-followup.md 第 6 条：骨架落地之后三份攻方腿只在句中写）。
#   ⑱ 派发提示常设要求的几行（records/2026-09-16-subagent拆分提案.md 第九十节 ⑤；清单 research/prompts/subagent-landing-audit-2026-10-22/b12-standing-requirements.md，各条判法在真派发提示上量过）：
#      批次（batch_verdict，常设要求 A2）：行首「批次：」一行（闭合了的围栏代码块里的不算）的值要形如 records/<文件>.md#<批号>：批号不空、不是占位，写法不限数字（「#12」「#批6」「#第 3 批后半」都认），
#      批号后面接句号、逗号、括注与别的话的照认；文件在本仓仓根或 git worktree 登记的哪一棵工作树里（lib_three_way_legs.py 的 registered_trees），路径里不许有 ..；
#      派 LONG_RUN_AGENTS（⑭ 那十种）没有这一行也拒，别的类型写了才判；值是 <填 …> 占位的交 ⑬。
#      草稿目录落点（scratch_line_root_verdict，常设要求 B7）：行首「草稿目录：」一行（认法只在 lib_prompt_scratch_line.py 的 scratch_line_values）点名的目录要落在工作根底下
#      （lib_work_root.py 的 configured_work_root，不看那份库的弄坏开关；$SINGLEFS_WORK_ROOT/、~/、$HOME/ 照那份库的 expand_written_path 展开），工作根本身、相对路径、工作根之外的都拒；
#      过渡期旧根 /tmp/claude-<uid> 开机被清空，这一判对新派发不认（只改这一判，lib_work_root.py 的 LEGACY_ROOT_IN_TRANSITION 照旧，④ ⑧ ⑯ ⑰ 与别的钩子照旧认旧根）。
#      写死台数与额度（host_quota_verdict，常设要求 B4）：派 LONG_RUN_AGENTS 时，正文（闭合了的围栏代码块、行首「线程上限：」「线程上限已判：」「内存上限：」「多机：」「观测：」五种行（「多机：」一行里的额度归 ⑭）、
#      行首「多机已判：」那一行与它后面连着的非空行、「」『』“”引着的都去掉）里写死主机资源的数（HOST_QUOTA：本机与第二台成对的「N 线程」（两段都写数、至少后一段带量词）、
#      「本机与第二台各 N 线程 / NG」「每台 / 各台 / 两台各 N 线程 / NG」、「两台合计 NG」「内存合计 NG」；「路」「路并行」与「线程」同等，量词与数之间可以插「各、都、均、分别」
#      接「跑、用、给、起、开、配、分、拿、派、上、按」这几个字，插别的字的（「每台默认 31 线程」「第二台负载 0」）不认；拆分提案第一百二十二节 ⑦）就拒，出路是删掉，
#      照「多机：」规范句与「线程上限：」一行，用户给了逐台参数的写「多机已判：」；写的是看到的现象（上一趟跑出来的、提醒里报的）的，单起一行「观测：…」或放进「」里。
#      单写一台的线程数、「N 核」「并行 N」不判（真提示上量过：那几种是观测与硬件说明，不是派给子 agent 的额度）；写死的是派法还是观测，钩子分不出，只认上面这几种字面。
#      自证在哪跑（selftest_location_verdict，常设要求 B10）：行首「自证在哪跑：」一行（闭合了的围栏代码块里的不算）的值里点名了工作根或过渡期旧根下的路径（草稿目录、仓副本）就拒；
#      「本仓主工作区」「不跑」放行，没写路径的说法（「副本里」）认不出、不判；占位的交 ⑬。
#      报告落点（report_location_verdict，拆分提案第五十六节 ③）：报告行（④ 那一种行首句首的认法，report_line_mentions）点名的、写成绝对路径的（/、~/、$HOME/、$SINGLEFS_WORK_ROOT/ 起头，
#      单独一个 / 不算）要落在工作根（configured_work_root）或本提示的仓根底下；/tmp 下的（过渡期旧根在内）与别处的都拒；相对路径、裸文件名不判；占位的交 ⑬。
#      不碰的文件（untouched_files_verdict，常设要求 D3，拆分提案第一百二十二节 ⑨）：派 implementation-writer、tooling-writer 要有一行行首标签（冒号前不到 40 个字）里带「不碰」的，
#      值不空（没有写「无」）；值空着的，下面连着的列表项算值；骨架打「不碰：<填 …>」。占位的交 ⑬。
#      关的是哪几条（addressed_section_verdict，常设要求 A5，只核节在）：派项目定义的类型（定义文件在），要有一节标题是「关的是哪几条」或「要回答的问题」（闭合围栏块里的不算），
#      节下到下一个标题之间至少一行不空；节里写得对不对钩子看不到。
#   ⑲ 门禁阶段（gate_stage_verdict，拆分提案第六十四节 ①）：提示叫子 agent 起 .claude/gate.d/ 这一层的一道（含 --check 点名单格）就拒，逐句引出来。认法（gate_stage_runs）：逐行
