                      and "禁读清单只列别的腿的报告与模型目录" in (forbidden_own_message or "") and "→ 怎么办" in (forbidden_own_message or "")))
        three_way_code, three_way_message = decide({"tool_input": {"subagent_type": "three-way-attack", "prompt": "草稿目录：~/.local/share/singlefs/work/x-r1-opus/\n报告：~/.local/share/singlefs/work/x-r1-opus/result.md\n"
                                                                    + FOOTER + thread_limit_line()}}, work, hook_dir)
        cases.append(("三方报告:拒绝说明给出形态与骨架", True,
