                      and "「~/.local/share/singlefs/work/x-r1-opus/result.md」" in (three_way_message or "") and "dispatch-prompt.py three-way-attack" in (three_way_message or "")
                      and "handback-guard.sh" in (three_way_message or "") and "→ 怎么办" in (three_way_message or "")))
