            case("三方报告:整份提示里只在子目录下有 -output.md，拒", "three-way-defense", "照正文交付，分段落盘到 research/prompts/x-r1/x-r1-sonnet-output.md。\n", 2, report=False, ignored=("三方腿报告行",)),
