        # $SINGLEFS_WORK_ROOT/<样本仓目录名>/ 展开后就是样本仓本身（一棵登记过的树）；展开后不在任何一棵树里的照拒（开关 leg-report-work-root-token-kept 下放行那两格红）
        saved_work_root = os.environ.get(work_roots.WORK_ROOT_VARIABLE)
