                 three_way_report_verdict("three-way-attack", f"报告：{work_root_written}\n", work) is None),
                ("三方报告:整份提示里写 ${SINGLEFS_WORK_ROOT}/ 起头、展开后解到本仓一棵树的报告路径，放行", True,
