                case(f"线程:派 {thread_type} 已判行没写理由照拒", thread_type, thread_extra + "线程上限已判：\n", 2, thread=False),
                case(f"线程:派 {thread_type} 线程上限写成占位只交骨架占位那一条", thread_type, thread_extra + "线程上限：<填 登记值>\n", 2, thread=False),
            ]
